/* ================= STATE ================= */
const store={
 get lang(){return localStorage.getItem('k_lang')||''}, set lang(v){localStorage.setItem('k_lang',v)},
 get ts(){return +(localStorage.getItem('k_ts')||0)}, set ts(v){localStorage.setItem('k_ts',String(v))},
 get favs(){try{return JSON.parse(localStorage.getItem('k_favs')||'[]')}catch(e){return[]}},
 set favs(v){localStorage.setItem('k_favs',JSON.stringify(v))},
 get routes(){try{return JSON.parse(localStorage.getItem('k_routes')||'[]')}catch(e){return[]}},
 set routes(v){localStorage.setItem('k_routes',JSON.stringify(v))}
};
let LANG=store.lang||'en';
const t=k=>(I18N[LANG]&&I18N[LANG][k]!=null)?I18N[LANG][k]:(I18N.en[k]!=null?I18N.en[k]:k);
const nm=o=>o?(o[LANG]!=null?o[LANG]:o.en):"";
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const track=(e,d)=>{try{console.debug('ev',e,d||'')}catch(x){}};

let plan=null,journey=null,userLoc=null,mapTheme='all',sq='',sf={};
/* ---- the day of the visit: today by default, any day within a year ---- */
function isoToday(){const d=new Date();return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());}
const pad2=n=>String(n).padStart(2,'0');
function isoDate(d){return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());}
function fromISO(iso){const p=(iso||isoToday()).split('-');return new Date(+p[0],+p[1]-1,+p[2]);}
function planDate(){return fromISO(plan&&plan.date);}
function planWeekday(){return planDate().getDay();}
function isToday(iso){return iso===isoToday();}
let calBase=null;   /* month currently shown in the picker */
const newPlan=()=>({step:0,mins:null,label:"",startType:"useLoc",
  start:{lat:CONFIG.centre.lat,lng:CONFIG.centre.lng},endType:"backToStart",
  end:{lat:CONFIG.centre.lat,lng:CONFIG.centre.lng},themes:[],mode:"car",pace:"balanced",
  who:"family",opts:{meal:true},res:null,alts:[],startClock:null,date:isoToday()});

const pad=n=>String(n).padStart(2,'0');
function clock(m){m=((Math.round(m)%1440)+1440)%1440;let h=Math.floor(m/60),x=m%60,
  ap=h<12?'am':'pm',hh=h%12||12;return hh+':'+pad(x)+ap;}
function dur(m){m=Math.round(m);const h=Math.floor(m/60),x=m%60;
  if(h&&x)return h+t('hr')+' '+x+t('min'); if(h)return h+t('hr'); return x+' '+t('min');}
const nowM=()=>{const d=new Date();return d.getHours()*60+d.getMinutes();};
const isOpen=d=>{const n=new Date();return Engine.openAt(d,n.getDay(),n.getHours()*60+n.getMinutes());};
const distTo=d=>Engine.roadKm(userLoc||CONFIG.centre,d);
const byId=id=>D.find(x=>x.id===id);

/* photo element; falls back to a themed plate when no image is set */
function photo(d,cls){
  const src=d.img&&IMG[d.img];
  if(src) return '<span class="ph '+(cls||'')+'"><img src="'+src+'" alt="'+esc(nm(d.name))+
    '" loading="lazy" onload="this.classList.add(\'in\')"></span>';
  const ic=(theme(d.themes[0])||{icon:'pin'}).icon;
  return '<span class="ph '+(cls||'')+'" style="display:grid;place-items:center;background:#DED7C8;color:#9A8F7C">'+
    svg(ic,'style="width:34%;height:34%"')+'</span>';
}
function statusPill(d){const o=isOpen(d);
  return '<span class="status '+(o?'open':'shut')+'">'+(o?t('open'):t('shut'))+'</span>';}

function navTo(id){
  const d=byId(id); if(!d) return;
  const o=userLoc||CONFIG.centre;
  const mm={car:'driving',taxi:'driving',twowheeler:'two-wheeler',public:'transit',walking:'walking'};
  const m=mm[(plan&&plan.mode)||'car']||'driving';
  const dst=d.placeId?'&destination='+encodeURIComponent(d.name.en)+'&destination_place_id='+d.placeId
                     :'&destination='+d.lat+','+d.lng;
  track('nav',{id}); window.open('https://www.google.com/maps/dir/?api=1&origin='+o.lat+','+o.lng+dst+'&travelmode='+m,'_blank','noopener');
}
let tT;
function toast(m){const e=document.getElementById('toast');e.textContent=m;e.classList.add('on');
  clearTimeout(tT);tT=setTimeout(()=>e.classList.remove('on'),2200);}
function openSheet(h){const s=document.getElementById('sheet');s.innerHTML='<div class="grab"></div>'+h;
  document.getElementById('scrim').classList.add('on');s.classList.add('on');}
function closeSheet(){document.getElementById('sheet').classList.remove('on');
  document.getElementById('scrim').classList.remove('on');}

/* ================= ROUTER ================= */
let navDir='';
const go=r=>{navDir='fwd';location.hash=r};
window.addEventListener('popstate',function(){navDir='rev'});
const route=()=>location.hash.replace(/^#/,'')||(LANG?'/home':'/start');
window.addEventListener('hashchange',render);

function render(){
  document.documentElement.lang=LANG;
  document.body.classList.toggle('big',store.ts===1);
  document.body.classList.toggle('bigger',store.ts===2);
  const r=route(),root=document.getElementById('root');
  if(r==='/start'||!LANG){root.innerHTML=vStart();return;}
  if(r==='/begin'){root.innerHTML=vBegin();return;}
  let b;
  if(r==='/home')b=vHome();
  else if(r==='/explore')b=vExplore();
  else if(r.indexOf('/theme/')===0)b=vTheme(r.split('/')[2]);
  else if(r==='/plan')b=vPlanner();
  else if(r==='/route')b=vRoute();
  else if(r==='/go')b=vJourney();
  else if(r==='/map')b=vMap();
  else if(r==='/saved')b=vSaved();
  else if(r==='/search')b=vSearch();
  else if(r==='/settings')b=vSettings();
  else if(r==='/credits')b=vCredits();
  else if(r.indexOf('/place/')===0)b=vPlace(r.split('/')[2]);
  else b=vHome();
  root.innerHTML=shell(b,r); navDir=''; loadWeather();
  if(r==='/map') setTimeout(initMap,60); else killMap();
  heroStop(); reelsStop();
  if(r==='/home'){ setTimeout(heroInit,70); setTimeout(function(){reelsInit('reelTrack')},90); }
  if(r.indexOf('/place/')===0) setTimeout(function(){reelsInit('reelTrackP')},90);
  if(r.indexOf('/place/')===0||r==='/route')window.scrollTo(0,0);
  if(r==='/search'){const i=document.getElementById('sIn');
    if(i){i.focus();i.setSelectionRange(i.value.length,i.value.length);}}
}
const TABS=['home','explore','plan','map','saved'];
function tabIndex(r){
  if(r==='/route'||r==='/go') return 2;
  if(r.indexOf('/theme/')===0) return 1;
  const i=TABS.indexOf(r.slice(1));
  return i<0?0:i;
}
function shell(inner,r){
  const tab=(id,ic,lb)=>{
    const on=r==='/'+id||(id==='plan'&&(r==='/route'||r==='/go'))||
             (id==='explore'&&r.indexOf('/theme/')===0);
    return '<button class="'+(on?'on':'')+'" onclick="go(\'/'+id+'\')"'+(on?' aria-current="page"':'')+'>'+
      svg(ic)+'<span>'+lb+'</span></button>';
  };
  return '<header><div class="hbar">'+
   '<button class="brand" onclick="go(\'/home\')"><span class="seal"><img src="'+LOGO_SM+'" alt=""></span>'+
   '<span class="wordmark"><b lang="'+LANG+'">'+(LANG==='hi'?CONFIG.brand.hi:CONFIG.brand.en)+'</b></span></button>'+
   '<span class="hspace"></span>'+wxChip()+
   '<button class="iconbtn" onclick="go(\'/search\')" aria-label="Search">'+svg('search')+'</button>'+
   '<button class="langbtn" onclick="flipLang()">'+(LANG==='hi'?'हिन्दी':'ENG')+'</button>'+
   '<button class="iconbtn" onclick="go(\'/settings\')" aria-label="Settings">'+svg('gear')+'</button>'+
   '</div></header><main class="screen '+navDir+'">'+inner+'</main>'+
   (r!=='/plan'?'<nav class="tab" style="--i:'+tabIndex(r)+'">'+tab('home','home',t('home'))+tab('explore','compass',t('explore'))+
     tab('plan','route',t('plan'))+tab('map','mapi',t('map'))+tab('saved','saved',t('saved'))+'</nav>':'');
}
const flipLang=()=>{LANG=LANG==='hi'?'en':'hi';store.lang=LANG;render();};
const setLang=l=>{LANG=l;store.lang=l;go('/begin');};
const setLangStay=l=>{LANG=l;store.lang=l;render();};

/* ================= SPLASH / LANGUAGE GATE ================= */
function vStart(){
  return '<div class="splash" id="splash">'+
   '<div class="rays" aria-hidden="true"></div>'+
   '<div class="crest">'+
     '<div class="halo" aria-hidden="true"></div>'+
     '<div class="seal"><img src="'+LOGO+'" alt="Kurukshetra Development Board"></div>'+
     '<div class="board">Kurukshetra Development Board</div>'+
     '<div class="boardhi" lang="hi">कुरुक्षेत्र विकास मंडल</div>'+
     '<div class="rule" aria-hidden="true"></div>'+
     '<h1>Kurukshetra<span class="dev" lang="hi">कुरुक्षेत्र</span></h1>'+
     '<div class="kos">48 Kos Tirtha Land</div>'+
   '</div>'+
   '<div class="gate">'+
     '<div class="ask">Choose your language<span class="h" lang="hi">अपनी भाषा चुनें</span></div>'+
     '<div class="langs">'+
       '<button class="lang" id="lang-en" onclick="pickLang(\'en\')" aria-label="Continue in English">'+
         '<span class="tick">'+svg('check')+'</span>'+
         '<span class="big">English</span><span class="sub">English</span></button>'+
       '<button class="lang" id="lang-hi" onclick="pickLang(\'hi\')" lang="hi" aria-label="हिन्दी में जारी रखें">'+
         '<span class="tick">'+svg('check')+'</span>'+
         '<span class="big dev">हिन्दी</span><span class="sub">Hindi</span></button>'+
     '</div>'+
     '<div class="foot">Change it anytime in Settings · <span lang="hi">सेटिंग्स में कभी भी बदलें</span></div>'+
   '</div></div>';
}
/* Confirm the tap, play the plate out, then land on the hub. */
function pickLang(l){
  if(window._gate) return; window._gate=1;
  LANG=l; store.lang=l; document.documentElement.lang=l;
  var el=document.getElementById('lang-'+l); if(el) el.classList.add('chosen');
  var sp=document.getElementById('splash');
  setTimeout(function(){ if(sp) sp.classList.add('leaving'); },170);
  setTimeout(function(){ if(sp) sp.classList.add('gone'); },300);
  setTimeout(function(){ window._gate=0; go('/begin'); },720);
}

function vBegin(){
  const c=(ic,cls,ti,de,fn)=>'<button class="hubcard" onclick="'+fn+'">'+
   '<span class="ic '+cls+'">'+svg(ic)+'</span><span style="min-width:0"><h3 lang="'+LANG+'">'+ti+
   '</h3><p>'+de+'</p></span><span class="go">'+svg('fwd')+'</span></button>';
  return '<div class="screen" style="padding:18px 16px calc(30px + env(safe-area-inset-bottom))">'+
   '<div style="display:flex;align-items:center;gap:11px;margin-bottom:26px">'+
     '<span class="seal" style="width:40px;height:40px">'+svg('rath')+'</span>'+
     '<div><div class="eyebrow">'+CONFIG.brand.sub+'</div>'+
     '<div class="display" style="font-size:calc(19px*var(--ts))" lang="'+LANG+'">'+(LANG==='hi'?CONFIG.brand.hi:CONFIG.brand.en)+'</div></div>'+
     '<span style="flex:1"></span><button class="langbtn" onclick="flipLang()">'+(LANG==='hi'?'हिन्दी':'ENG')+'</button></div>'+
   '<h1 class="display" style="font-size:calc(25px*var(--ts));line-height:1.22;margin-bottom:20px" lang="'+LANG+'">'+t('howExplore')+'</h1>'+
   '<div class="hub stagger">'+
     c('route','',t('planVisit'),t('planVisitD'),"go('/plan')")+
     c('tara','brass',t('highlights'),t('highlightsD'),"go('/explore')")+
     c('compass','slate',t('browse'),t('browseD'),"go('/explore')")+
     c('pin','slate',t('nearMe'),t('nearMeD'),"askLoc(function(){go('/map')})")+
   '</div></div>';
}

/* ================= HOME ================= */
const WINDOWS=[["1h",60],["2h",120],["3h",180],["4h",240],["6h",360],
  [{en:"Half day",hi:"आधा दिन"},300],[{en:"Full day",hi:"पूरा दिन"},480],
  [{en:"2 days",hi:"2 दिन"},960],[{en:"3 days",hi:"3 दिन"},1440]];

function fcard(d){
  return '<button class="fcard" onclick="go(\'/place/'+d.id+'\')">'+photo(d)+
   '<span class="in" style="display:block"><h3 lang="'+LANG+'">'+esc(nm(d.name))+'</h3>'+
   '<p>'+esc(nm(d.short))+'</p><span class="meta">'+statusPill(d)+
   '<span class="tag">'+svg('clock')+dur(d.visit.rec)+'</span></span></span></button>';
}
function pcard(d){
  return '<button class="card pcard" onclick="go(\'/place/'+d.id+'\')">'+photo(d)+
   '<span class="body"><h3 lang="'+LANG+'">'+esc(nm(d.name))+'</h3>'+
   '<span class="alt" lang="'+(LANG==='hi'?'en':'hi')+'">'+esc(LANG==='hi'?d.name.en:d.name.hi)+'</span>'+
   '<span class="sub">'+esc(nm(d.short))+'</span>'+
   '<span class="meta">'+statusPill(d)+
   '<span class="tag">'+svg('clock')+dur(d.visit.rec)+'</span>'+
   '<span class="tag">'+svg('pin')+distTo(d)+' '+t('km')+'</span></span></span></button>';
}

