function vSaved(){
  const favs=store.favs.map(byId).filter(Boolean),rs=store.routes;
  if(!favs.length&&!rs.length)return '<div class="phead"><h1 class="display" lang="'+LANG+'">'+t('saved')+'</h1></div>'+
   '<div class="empty">'+svg('saved')+'<p class="t">'+t('savedNone')+'</p><p>'+t('savedNoneD')+'</p>'+
   '<button class="btn primary" style="max-width:230px;margin:18px auto 0" onclick="go(\'/plan\')">'+t('planVisit')+'</button></div>';
  return '<div class="phead"><h1 class="display" lang="'+LANG+'">'+t('saved')+'</h1></div>'+
   (rs.length?'<div class="sec" style="margin-top:2px"><div class="sec-head"><h2 style="font-size:calc(17px*var(--ts))">'+t('savedRoutes')+'</h2></div>'+
     '<div class="plist stagger">'+rs.map(rRow).join('')+'</div></div>':'')+
   (favs.length?'<div class="sec"><div class="sec-head"><h2 style="font-size:calc(17px*var(--ts))">'+t('savedPlaces')+'</h2></div>'+
     '<div class="plist stagger">'+favs.map(pcard).join('')+'</div></div>':'');
}
function rRow(r){
  const ns=r.ids.map(i=>{const d=byId(i);return d?nm(d.name):''}).filter(Boolean);
  return '<div class="card" style="padding:13px"><div style="display:flex;align-items:center;gap:11px">'+
   '<span style="width:38px;height:38px;border-radius:10px;background:var(--clay-wash);color:var(--clay);'+
   'display:grid;place-items:center;flex:0 0 auto">'+svg('route')+'</span>'+
   '<div style="flex:1;min-width:0"><b class="display" style="font-size:calc(15px*var(--ts))">'+esc(r.title)+'</b>'+
   '<div class="muted" style="font-size:calc(12px*var(--ts))">'+ns.length+' '+t('stops')+' · '+
   new Date(r.at).toLocaleDateString(LANG==='hi'?'hi-IN':'en-IN')+'</div></div>'+
   '<button class="iconbtn" onclick="delRoute(\''+r.id+'\')" aria-label="'+t('removedT')+'">'+svg('close')+'</button></div>'+
   '<div class="muted" style="font-size:calc(12.5px*var(--ts));margin-top:9px;line-height:1.65">'+ns.map((n,i)=>(i+1)+'. '+esc(n)).join(' · ')+'</div>'+
   '<button class="btn ghost sm" style="margin-top:11px" onclick="loadRoute(\''+r.id+'\')">'+svg('play')+t('startTour')+'</button></div>';
}
const delRoute=id=>{store.routes=store.routes.filter(r=>r.id!==id);toast(t('removedT'));render();};
function loadRoute(id){const r=store.routes.find(x=>x.id===id);if(!r)return;
  plan=newPlan();plan.mins=r.mins||240;plan.label=r.title;plan.mode=r.mode||'car';
  plan.pace=r.pace||'balanced';plan.themes=r.themes||[];plan.startClock=nowM();
  plan.res=Engine.build({budgetMin:plan.mins,start:plan.start,end:plan.end,interests:[],mode:plan.mode,
    pace:plan.pace,startClock:plan.startClock,weekday:planWeekday(),filters:{meal:true},onlyIds:r.ids});
  plan.alts=[];go('/route');}

function vSearch(){
  const q=sq.trim().toLowerCase();
  const res=D.filter(d=>{
    if(q){const hay=(d.name.en+' '+d.name.hi+' '+nm(d.short)+' '+d.themes.join(' ')).toLowerCase();
      if(hay.indexOf(q)<0)return false;}
    if(sf.open&&!isOpen(d))return false;
    if(sf.free&&!d.free)return false;
    if(sf.indoor&&!d.indoor)return false;
    if(sf.short&&d.visit.rec>40)return false;
    return true;}).sort((a,b)=>b.rank-a.rank);
  const f=(k,lb)=>'<button class="chip'+(sf[k]?' on':'')+'" onclick="sf.'+k+'=!sf.'+k+';render()">'+lb+'</button>';
  return '<div class="phead"><button class="back" onclick="history.back()" aria-label="'+t('back')+'">'+svg('back')+'</button>'+
   '<h1 class="display" style="font-size:calc(19px*var(--ts))" lang="'+LANG+'">'+t('searchPh')+'</h1></div>'+
   '<div class="search">'+svg('search')+'<input id="sIn" type="search" placeholder="'+t('searchPh')+
   '" value="'+esc(sq)+'" oninput="onSearch(this.value)">'+
   (sq?'<button class="iconbtn" style="width:32px;min-width:32px" onclick="sq=\'\';render()">'+svg('close')+'</button>':'')+'</div>'+
   '<div class="hscroll" style="margin-top:11px">'+f('open',t('fOpen'))+f('free',t('fFree'))+
   f('indoor',t('fIndoor'))+f('short',t('fShort'))+'</div>'+
   (res.length?'<div class="plist stagger">'+res.map(pcard).join('')+'</div>'
    :'<div class="empty">'+svg('search')+'<p class="t">'+t('nothing')+'</p><p>'+t('nothingD')+'</p></div>');
}
let sd;const onSearch=v=>{sq=v;clearTimeout(sd);sd=setTimeout(()=>render(),170);};

